insert into public.services (id, slug, title, summary, description, icon, deliverables, price_from_cents, duration_label, featured, sort_order) values
  ('00000000-0000-4000-8000-000100000001', 'business-strategy', 'Business Strategy', 'A clear plan for where to compete, how to win and what to stop doing.', 'We work with owners and executive teams to turn ambition into a strategy the whole business can act on. That means an honest look at your market and numbers, a small set of priorities, and a 12-month roadmap with owners and measures.

You leave with a strategy document your team understands and a quarterly rhythm for reviewing progress.', 'compass', array['Market and competitor review', 'Strategy workshop with your leadership team', '12-month roadmap with owners and measures', 'Quarterly review sessions'], 4500000, '4–8 weeks', true, 1),
  ('00000000-0000-4000-8000-000100000002', 'funding-readiness', 'Funding & Investor Readiness', 'Get your business ready to raise: the numbers, the story and the paperwork.', 'Most funding applications fail on preparation, not on the idea. We build the financial model, pitch deck and data room that banks, development funders and investors expect to see, and we rehearse the hard questions with you.

We also help you choose the right kind of money for your stage: debt, equity, grants or a blend.', 'trending-up', array['Three-year financial model', 'Investor pitch deck', 'Data room checklist and review', 'Funder shortlist and pitch rehearsal'], 3500000, '3–6 weeks', true, 2),
  ('00000000-0000-4000-8000-000100000003', 'operations-improvement', 'Operations Improvement', 'Find where time and money leak out of the business, and fix it.', 'We map how work really flows through your business, measure where it stalls, and redesign the process with the people who do the work. The focus is on changes your team can sustain without us.', 'settings', array['Process map of core operations', 'Cost and bottleneck analysis', 'Improvement plan with quick wins', 'Implementation support for 90 days'], 3000000, '6–12 weeks', true, 3),
  ('00000000-0000-4000-8000-000100000004', 'compliance-governance', 'Compliance & Governance', 'B-BBEE, POPIA and board governance handled properly, without the jargon.', 'Compliance should protect the business, not paralyse it. We assess where you stand, close the gaps that carry real risk, and set up simple routines so you stay compliant as you grow.', 'shield-check', array['Compliance gap assessment', 'POPIA policies and data register', 'B-BBEE scorecard planning', 'Board and governance framework'], 2500000, '4–6 weeks', false, 4),
  ('00000000-0000-4000-8000-000100000005', 'leadership-development', 'Leadership Development', 'Coaching and team programmes for managers stepping up to lead.', 'Growing businesses outgrow their management habits. We coach individual leaders and run practical programmes for management teams on decision making, delegation, performance conversations and running effective meetings.', 'users', array['Leadership assessment', 'One-to-one executive coaching', 'Management team programme', 'Progress review after six months'], 1800000, '3–6 months', false, 5),
  ('00000000-0000-4000-8000-000100000006', 'market-entry', 'Market Entry & Growth', 'Test a new market or product before you commit serious money to it.', 'We size the opportunity, talk to real customers, and design a low-cost pilot so that your expansion decision rests on evidence. If the numbers work, we help you build the go-to-market plan.', 'globe', array['Market sizing and customer research', 'Pricing and positioning', 'Pilot design and measurement', 'Go-to-market plan'], 4000000, '6–10 weeks', false, 6)
on conflict (id) do nothing;

insert into public.team_members (id, slug, name, role_title, bio, photo_url, credentials, linkedin_url, sort_order) values
  ('00000000-0000-4000-8000-000200000001', 'thandi-mokoena', 'Thandi Mokoena', 'Managing Partner, Strategy & Funding', 'Thandi has spent 15 years helping growing businesses plan and fund their next stage. She began her career in corporate finance before moving into advisory work with owner-managed companies across manufacturing, retail and services.', null, array['CA(SA)', 'MBA', '15 years in advisory'], null, 1),
  ('00000000-0000-4000-8000-000200000002', 'david-naidoo', 'David Naidoo', 'Partner, Operations & Governance', 'David leads our operations and governance work. An industrial engineer by training, he has run plants and distribution networks and now helps leadership teams build businesses that run well without heroics.', null, array['Pr.Eng', 'Lean Six Sigma Black Belt', 'Certified Director'], null, 2)
on conflict (id) do nothing;

insert into public.case_studies (id, slug, title, client_name, industry, summary, challenge, approach, outcome, metrics, sort_order) values
  ('00000000-0000-4000-8000-000300000001', 'regional-logistics-turnaround', 'Restoring margin at a regional logistics company', 'Regional logistics company', 'Logistics', 'A family-owned fleet operator was growing revenue while profit fell. We found the cause and rebuilt the pricing model.', 'Revenue had grown for three years while net margin halved. The owners suspected fuel costs, but had no route-level view of profitability.', 'We built a cost-to-serve model for every route and customer, which showed that a fifth of contracts were loss-making. We renegotiated or exited those contracts, restructured dispatch, and introduced a weekly margin review.', 'Margin recovered within two quarters and the business secured asset finance for fleet renewal on the strength of the new reporting.', '[{"label":"Net margin","value":"+6 pts"},{"label":"Loss-making routes","value":"−80%"},{"label":"Payback","value":"5 months"}]'::jsonb, 1),
  ('00000000-0000-4000-8000-000300000002', 'agri-processor-growth-funding', 'Raising growth funding for an agri-processor', 'Agri-processing business', 'Agriculture', 'A profitable processor needed capital for a second line. We prepared the business for funders and ran the process.', 'The founders had been turned down twice. Their financials were sound, but the application did not explain the growth case or the risks.', 'We rebuilt the financial model, wrote the investment memorandum, organised the data room, and approached a shortlist of development funders and banks suited to the deal size.', 'The business received two offers and closed a blended debt facility, with the second processing line commissioned on schedule.', '[{"label":"Capital raised","value":"R18m"},{"label":"Time to close","value":"14 weeks"},{"label":"Jobs created","value":"40"}]'::jsonb, 2),
  ('00000000-0000-4000-8000-000300000003', 'professional-services-popia', 'POPIA compliance for a professional services firm', 'Professional services firm', 'Professional services', 'A 60-person firm holding sensitive client records needed to be compliant, and able to prove it to its own clients.', 'Client data sat in email, shared drives and personal devices. A large client had made POPIA compliance a condition of contract renewal.', 'We mapped all personal information, wrote practical policies, trained every staff member, and set up an incident response routine.', 'The firm passed its client''s audit and renewed the contract. Compliance is now part of onboarding for new staff.', '[{"label":"Staff trained","value":"100%"},{"label":"Audit findings","value":"0"},{"label":"Delivery time","value":"6 weeks"}]'::jsonb, 3)
on conflict (id) do nothing;

insert into public.testimonials (id, quote, author_name, author_title, company, sort_order) values
  ('00000000-0000-4000-8000-000400000001', 'For the first time we can see which customers make us money. That one piece of work changed how we run the business.', 'Operations Director', 'Operations Director', 'Regional logistics company', 1),
  ('00000000-0000-4000-8000-000400000002', 'We had been rejected twice. They rebuilt our case from the numbers up and stayed with us until the money was in the bank.', 'Co-founder', 'Co-founder', 'Agri-processing business', 2),
  ('00000000-0000-4000-8000-000400000003', 'Practical, direct and never condescending. The course gave my managers a shared language for the finances.', 'Chief Executive', 'Chief Executive', 'Manufacturing group', 3)
on conflict (id) do nothing;

insert into public.courses (id, slug, title, summary, description, level, duration_label, format, price_cents, cover_url, outcomes, featured, sort_order, published) values
  ('00000000-0000-4000-8000-000500000001', 'funding-ready', 'Funding Ready: Prepare Your Business to Raise Capital', 'A step-by-step programme for founders who want to approach banks, funders or investors with confidence.', 'This course takes you through everything a funder will ask for. You will build your own financial model, write your pitch and assemble your data room as you go, so that you finish with an application you can actually submit.

It is designed for owners of established small and medium businesses. No finance background is needed.', 'Intermediate', '6 hours', 'self_paced', 249900, null, array['Choose the right type of funding for your stage', 'Build a three-year financial model', 'Write a pitch deck funders want to read', 'Assemble a complete data room'], true, 1, true),
  ('00000000-0000-4000-8000-000500000002', 'finance-for-managers', 'Finance for Non-Financial Managers', 'Read financial statements, build a budget and make decisions using the numbers.', 'Managers make financial decisions every day, often without being taught how the numbers fit together. This course explains the income statement, balance sheet and cash flow in plain language and shows you how to use them.', 'Beginner', '4 hours', 'self_paced', 149900, null, array['Read the three main financial statements', 'Build and defend a departmental budget', 'Tell profit from cash', 'Use margins and ratios to make decisions'], true, 2, true),
  ('00000000-0000-4000-8000-000500000003', 'popia-essentials', 'POPIA Essentials for Small Business', 'A short, free introduction to what the Protection of Personal Information Act requires of you.', 'A practical overview of POPIA for owners and managers: what counts as personal information, the eight conditions for lawful processing, and the first five steps every business should take.', 'Beginner', '1 hour', 'self_paced', 0, null, array['Know what counts as personal information', 'Understand the eight conditions for lawful processing', 'Take the first five compliance steps'], true, 3, true)
on conflict (id) do nothing;

